const e=value=>String(value??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const money=value=>new Intl.NumberFormat("tr-TR",{style:"currency",currency:"TRY"}).format(Number(value||0));
const date=value=>value?new Intl.DateTimeFormat("tr-TR",{dateStyle:"long"}).format(new Date(value)):"Henüz yok";
const commissionStatus={pending:"Kesinleşiyor",payable:"Ödenebilir",pending_payout:"Ödeme hazırlanıyor",paid:"Ödendi",cancelled:"İptal edildi"};
export function partnerPanelView({summary,referrals=[],commissions=[]}){if(!summary)return `<section class="card teacher-partner-card"><h2>Öğretmen Partner Programı</h2><p>Ücretsiz partner profilinizi oluşturup kod başvurunuzu başlatın.</p><div class="button-row"><button class="button primary" data-action="register-teacher-partner">Partner profilini oluştur</button><button class="button secondary" data-action="buy-teacher-monthly">Öğretmen erişimi satın al</button></div></section>`;
 const locked=!summary.has_full_access;return `<section class="teacher-partner" data-teacher-partner-panel><div class="page-head"><div><p class="eyebrow">ÖĞRETMEN PARTNER</p><h1>Partner ve erişim merkezi</h1><p>Partner paneliniz erişim süreniz bitse de açık kalır.</p></div></div>${locked?`<article class="card feedback incorrect"><strong>Tam öğretmen erişiminiz sona erdi.</strong><p>Yeni bir ücretli öğrenci getirerek 30 gün kazanabilir veya 199 TL ile bir ay uzatabilirsiniz.</p></article>`:""}<div class="partner-grid"><article class="card"><h2>Partner kodu</h2><strong class="partner-code" data-partner-code>${e(summary.partner_code)}</strong><div class="button-row"><button class="button primary" data-action="copy-partner-code">Kodu kopyala</button><button class="button secondary" data-action="copy-partner-link">Bağlantıyı kopyala</button></div></article><article class="card"><h2>Erişim</h2><p>Kazanılan: <strong>${e(summary.earned_access_days)} gün</strong></p><p>Kalan: <strong>${e(summary.remaining_access_days)} gün</strong></p><p>Bitiş: <strong>${date(summary.access_ends_at)}</strong></p><button class="button primary" data-action="buy-teacher-monthly">199 TL ile 1 ay uzat</button></article><article class="card"><h2>Satışlar</h2><p>Toplam farklı öğrenci: <strong>${e(summary.total_students)}</strong></p><p>Bu ay: <strong>${e(summary.students_this_month)}</strong></p></article><article class="card"><h2>Komisyon</h2><p>Ödenebilir: <strong>${money(summary.payable_commission)}</strong></p><p>Ödeme hazırlanıyor: <strong>${money(summary.pending_payout_commission)}</strong></p><p>Ödenmiş: <strong>${money(summary.paid_commission)}</strong></p></article></div><section class="card"><h2>Son hareketler</h2>${commissions.length?commissions.slice(0,10).map(x=>`<p>${date(x.earned_at)} · ${money(x.commission_amount)} · ${e(commissionStatus[x.status]||"Bilinmiyor")}</p>`).join(""):"<p>Henüz komisyon hareketi yok.</p>"}<p class="meta">Nitelikli öğrenci hareketi: ${referrals.length}</p></section></section>`}
export function teacherAccessLockView(){return `<section class="card teacher-access-lock"><h1>Tam öğretmen erişiminiz sona erdi.</h1><p>Yeni bir ücretli öğrenci getirerek 30 gün kazanabilir veya 199 TL ile bir ay uzatabilirsiniz.</p><button class="button primary" data-route="teacher">Partner paneline dön</button></section>`}
export function adminPartnerView(rows=[],payouts=[]){return `<section class="teacher-partner admin-partners"><div class="page-head"><div><p class="eyebrow">YÖNETİCİ</p><h1>Öğretmen partner yönetimi</h1></div><button class="button secondary" data-route="account">Hesaba dön</button></div><section class="card" data-admin-payouts><h2>Bekleyen payout'lar</h2>${payouts.length?payouts.map(p=>`<article data-admin-payout="${e(p.id)}"><h3>${e(p.teacher_display_name)}</h3><p>${date(p.period_start)} – ${date(p.period_end)} · <strong>${money(p.amount)}</strong></p><p>Bağlı kazanç: ${e(p.earning_count)} · Oluşturulma: ${date(p.created_at)}</p><label class="field">İptal notu<input data-payout-cancel-note maxlength="500"></label><div class="button-row"><button class="button primary" data-action="admin-mark-payout-paid">Ödendi işaretle</button><button class="button secondary" data-action="admin-cancel-payout">Payout'ı iptal et</button></div><p data-payout-result aria-live="polite"></p></article>`).join(""):"<p>Bekleyen payout yok.</p>"}</section>${rows.length?rows.map(row=>`<article class="card" data-admin-partner="${e(row.teacher_id)}"><h2>${e(row.display_name)}</h2><form data-admin-partner-form><input type="hidden" name="teacherId" value="${e(row.teacher_id)}"><div class="partner-grid"><label class="field">Partner kodu<input name="partnerCode" value="${e(row.partner_code)}" required></label><label class="field">Durum<select name="status"><option${row.status==="active"?" selected":""}>active</option><option${row.status==="pending"?" selected":""}>pending</option><option${row.status==="suspended"?" selected":""}>suspended</option></select></label><label class="field">Komisyon oranı<input name="commissionRate" type="number" min="0" max="1" step="0.01" value="${e(row.commission_rate)}"></label><label class="field">Yönetici notu<input name="adminNote" maxlength="500"></label></div><p>Öğrenci: <strong>${e(row.referral_count)}</strong> · Ödenebilir: <strong>${money(row.payable_commission)}</strong> · Erişim: <strong>${date(row.access_ends_at)}</strong></p><div class="button-row"><button class="button primary" data-action="admin-save-partner">Kaydet</button><button type="button" class="button secondary" data-action="admin-create-payout">Bu ay payout oluştur</button></div><p data-admin-partner-status aria-live="polite"></p></form></article>`).join(""):"<article class='card'><p>Henüz partner profili yok.</p></article>"}</section>`}
